documents.spec:
yamaa: "1.0"
type: spec
domain: TEST
keys: [ID]
input:
  SRC: {path: input.csv, types: {ID: int, D: date, R: date}}
output: {path: result.csv, columns: [ID, SD, EPOCH]}
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - name: SD
    type: int
    derivation: {study_day: {source: SRC.D, reference: SRC.R}}
  - name: EPOCH
    type: int
    derivation: {to_epoch_day: {source: SRC.D}}

edits.to:
    derivation: {to_epoch_day: {source: SRC.D}}
